x_938076_backup_0_backup_scripts.script:
  //Fix Script
  try { // this will be in initalize
      var businessProcessStageStatus = {};
      var bPSt = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage');
      bPSt.addQuery('ctac_code', '!=', '');
      bPSt.query();
      invalid_order_type = gs.getProperty("x_hsb11_hsbc_mss_o.invalid_order_types"); //MSSRBXCE-559

      /**
       * MSSOTIQUBE-1243
       * Processes a list of business process stages(bPSt) 
       * Populates an object (businessProcessStageStatus) with details about each stage
       */
      while (bPSt.next()) {
          businessProcessStageStatus[bPSt.ctac_code] = {
              isexception: bPSt.is_exception.toString(),
              dur: bPSt.expected_duration.toString(),
              dur_ts: new GlideDateTime(bPSt.expected_duration).getNumericValue(), //get Timestamp from expected duration field
              busProcess: bPSt.business_process.toString(),
              status: bPSt.status.toString(),
              status_sys_id: bPSt.sys_id.toString()
          };
      }
      //this.businessProcessStageStatus = businessProcessStageStatus;
      //MT543cancel_request

      gs.info(businessProcessStageStatus['MT543cancel_request']['isexception']);

  } catch (e) {
      gs.error('[MSS EVENT UTIL] Exception in initialize(): ' + e.message + "\n" + e.stack); //MSSOTIQUBE-1243
  }

  // this.businessProcessStageStatus[eventstatus]["isexception"]; // access this in script include

  //fix script


